import {fishResult} from './fishing-coins-model.mjs?v=decimal2';
import {confirmDialog} from './site-dialogs.mjs?v=1';
const data=await(await fetch('/fishing-data.json')).json(),key='tatari-fishing-coins-v1',fmt=n=>n.toLocaleString('en-US'),grid=document.getElementById('fish-grid');let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')}catch{}if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};
const cards=[];const order=[1, 39, 38, 28, 27, 23, 20, 5, 4, 3, 2, 41, 40, 32, 31, 30, 29, 26, 24, 21, 9, 8, 7, 6, 43, 42, 37, 36, 35, 34, 33, 25, 22, 17, 16, 15, 14, 13, 12, 11, 10];data.fish.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
for(const fish of data.fish){const card=document.createElement('article');card.className='fish-card quality-'+fish.quality;card.innerHTML=`<div class="fish-art"><img data-fish-art alt="" width="360" height="360" loading="lazy"><div class="fish-current"><img src="/guide-assets/fishing/goldcoin.png" alt="" width="25" height="25"><strong>—</strong></div></div><h2>${fish.name}</h2><label for="fish-${fish.id}">Weight · kg</label><input id="fish-${fish.id}" type="text" inputmode="decimal" aria-label="${fish.name} best weight in kg" autocomplete="off" placeholder="Weight…" aria-describedby="fish-error-${fish.id}"><p class="fish-error" id="fish-error-${fish.id}"></p><div class="fish-gain"><span>Can add</span><span class="fish-gain-value"><img src="/guide-assets/fishing/goldcoin.png" alt="Gold coins" width="18" height="18"><strong>—</strong></span></div>`;card.querySelector('[data-fish-art]').src=fish.icon;const input=card.querySelector('input');input.value=typeof saved[fish.id]==='string'?saved[fish.id]:'';input.addEventListener('input',()=>{saved[fish.id]=input.value;try{localStorage.setItem(key,JSON.stringify(saved))}catch{document.getElementById('calculator-status').hidden=false;document.getElementById('calculator-status').textContent='Browser storage unavailable. Weights will last for this visit only.'}update()});grid.append(card);cards.push({fish,card,input})}
function update(){let total=0,gain=0,count=0,invalid=0;for(const {fish,card,input} of cards){const r=fishResult(input.value,fish),valid=r.state==='valid';input.setAttribute('aria-invalid',String(r.state==='invalid'));card.classList.toggle('has-record',valid);card.querySelector('.fish-error').textContent=r.message||'';card.querySelector('.fish-current strong').textContent=valid?fmt(r.current):'—';card.querySelector('.fish-gain strong').textContent=valid?'+'+fmt(r.gain):'—';if(valid){total+=r.current;gain+=r.gain;count++}if(r.state==='invalid')invalid++}document.getElementById('current-total').textContent=fmt(total);document.getElementById('gain-total').textContent='+'+fmt(gain);document.getElementById('record-count').textContent=count+' / '+cards.length+' records entered'+(invalid?' · '+invalid+' invalid weights excluded':'')}
document.getElementById('fish-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase().trim();let visible=0;for(const {fish,card} of cards){card.hidden=!fish.name.toLowerCase().includes(q);if(!card.hidden)visible++}document.getElementById('no-fish').hidden=!!visible});
document.getElementById('reset-fish').onclick=async()=>{if(!cards.some(c=>c.input.value))return;if(!await confirmDialog('Clear all saved fish weights?',{title:'Clear weights',action:'Clear weights'}))return;saved={};try{localStorage.removeItem(key)}catch{}for(const c of cards)c.input.value='';update()};update();

document.getElementById('set-max-fish').onclick=()=>{for(const {fish,input} of cards){input.value=String((fish.maxRaw-1)/100);saved[fish.id]=input.value}try{localStorage.setItem(key,JSON.stringify(saved))}catch{document.getElementById('calculator-status').hidden=false;document.getElementById('calculator-status').textContent='Browser storage unavailable. Weights will last for this visit only.'}update()};
